import{_ as s,c as t,o as n,j as e,a as l}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"震下巽上 益：","description":"京氏易傳 - 震下巽上 益：","frontmatter":{"title":"震下巽上 益：","description":"京氏易傳 - 震下巽上 益："},"headers":[],"relativePath":"classics/jingshi/045.md","filePath":"classics/jingshi/045.md"}'),i={name:"classics/jingshi/045.md"};function r(c,a,o,p,d,m){return n(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"震下巽上-益",tabindex:"-1"},[l("震下巽上 益： "),e("a",{class:"header-anchor",href:"#震下巽上-益","aria-label":"Permalink to “震下巽上 益：”"},"​")],-1),e("p",null,"天地不交曰否。六二陰上柔剛，九四下降積陰，故為益。《易》曰：“損上益下”。雷動風行，男下女上。【震男，巽女。】陽益陰，君益於民之象也。互見坤，坤道柔順。又外見艮，艮止陽益陰，止於陽，柔道行也。【內外順動，風雷益。四象分明，剛柔定矣。】與震為飛伏。【庚辰土，辛酉金。】六三三公居世，上九宗廟為應。",-1),e("p",null,"建始甲辰至己酉，【清明，秋分。】積算起己酉至戊申，週而復始。土金入震巽。【起積配風雷益卦起宮。】",-1),e("p",null,"五星從位起歲星，【木星入卦。】計宿從位降庚辰，（虎易注：計宿，即是斗宿。）【二十八宿，分計宿入風雷益六二庚辰土上。】分氣候二十八。【起二十八數，積算吉凶，週而復始。】",-1),e("p",null,"陰陽二木，合金土配象，四時運轉，六位交分，休廢旺生，吉凶見乎動爻。配日月星辰進退，運氣升降，復當何位。【金、水、木、火、土。】",-1),e("p",null,"適變於外，陽入陰爻。二象健而動，屬於天地也。【天陽，震雷亦陽也。二氣相激，動而健，天行也。】陰陽相蕩，次降入天雷無妄卦。",-1)])])}const f=s(i,[["render",r]]);export{_ as __pageData,f as default};
